public class FeeStructure { private final String eventName; private final double basic,standard,premium; public FeeStructure(String eventName,double basic,double standard,double premium){this.eventName=eventName;this.basic=basic;this.standard=standard;this.premium=premium;} public String getEventName(){return eventName;} public double getPrice(String packageName){if(packageName.equalsIgnoreCase("Basic"))return basic;if(packageName.equalsIgnoreCase("Standard"))return standard;if(packageName.equalsIgnoreCase("Premium"))return premium;return -1;} public String toFileLine(){return eventName+"|"+basic+"|"+standard+"|"+premium;} }
